import{_ as e,o,c as a,a2 as s}from"./chunks/framework.p5LmaamA.js";const u=JSON.parse('{"title":"JWT 认证体系中集成 Redis — 设计思路","description":"","frontmatter":{},"headers":[],"relativePath":"10其他/Redis思路.md","filePath":"10其他/Redis思路.md","lastUpdated":1789006814000}'),d={name:"10其他/Redis思路.md"};function n(r,t,i,l,h,p){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="jwt-认证体系中集成-redis-—-设计思路" tabindex="-1">JWT 认证体系中集成 Redis — 设计思路 <a class="header-anchor" href="#jwt-认证体系中集成-redis-—-设计思路" aria-label="Permalink to &quot;JWT 认证体系中集成 Redis — 设计思路&quot;">​</a></h1><h2 id="一、是什么" tabindex="-1">一、是什么 <a class="header-anchor" href="#一、是什么" aria-label="Permalink to &quot;一、是什么&quot;">​</a></h2><p>在已有的 JWT 无状态认证体系上引入 Redis，为 token 增加&quot;可主动失效&quot;的能力。本质是在 JWT 的无状态优势之上，叠加一层有状态的控制面，用 Redis 的 key-value 存储来追踪 token 的生命周期状态。</p><h2 id="二、为什么需要" tabindex="-1">二、为什么需要 <a class="header-anchor" href="#二、为什么需要" aria-label="Permalink to &quot;二、为什么需要&quot;">​</a></h2><p>纯粹 JWT 认证有三处缺陷：</p><table tabindex="0"><thead><tr><th>痛点</th><th>说明</th></tr></thead><tbody><tr><td><strong>Token 无法主动失效</strong></td><td>签发后直到过期前一直有效，改密码、被封禁后旧 token 照用不误</td></tr><tr><td><strong>RefreshToken 形同虚设</strong></td><td>后端生成了双令牌，但前端没存 RT，续期能力没有落地</td></tr><tr><td><strong>无法控制多端登录</strong></td><td>同一账号多设备登录时无法踢人，也无法限制同时在线数</td></tr></tbody></table><p>引入 Redis 就是为了补上这三个缺口，让 JWT 从&quot;全无状态&quot;变成&quot;核心路径无状态、控制面有状态&quot;的混合架构。</p><h2 id="三、核心方案" tabindex="-1">三、核心方案 <a class="header-anchor" href="#三、核心方案" aria-label="Permalink to &quot;三、核心方案&quot;">​</a></h2><h3 id="_3-1-三个-redis-切入场景" tabindex="-1">3.1 三个 Redis 切入场景 <a class="header-anchor" href="#_3-1-三个-redis-切入场景" aria-label="Permalink to &quot;3.1 三个 Redis 切入场景&quot;">​</a></h3><h4 id="场景一-token-黑名单-—-精准标记-哪个-token-失效" tabindex="-1">场景一：Token 黑名单 — 精准标记&quot;哪个 token 失效&quot; <a class="header-anchor" href="#场景一-token-黑名单-—-精准标记-哪个-token-失效" aria-label="Permalink to &quot;场景一：Token 黑名单 — 精准标记&quot;哪个 token 失效&quot;&quot;">​</a></h4><p>适合登出、改密场景。把要失效的 token 的唯一标识写入 Redis，TTL 设为 token 剩余过期时间（自动清理，不占永久内存）。</p><p><strong>两种实现路径</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>A — jti 黑名单</td><td>Redis 存 <code>token:black:&lt;jti&gt;</code>，逐 token 标记失效</td><td>精准控制单个 token</td><td>每个失效 token 一条 key，改密需全量标记</td></tr><tr><td>B — 用户版本号 ★</td><td>Redis 存 <code>user:version:&lt;userId&gt;</code> (整数)，token 中嵌入版本号，校验时比对</td><td>一次 INCR 踢掉该用户所有旧 token，极省空间</td><td>不能&quot;只踢某个设备&quot;</td></tr></tbody></table><p><strong>推荐方案 B</strong>。版本号自增，永不回退：登出 → <code>INCR</code>，改密 → <code>INCR</code>。拦截器校验时拿 token 里的版本号与 Redis 当前版本号比对，不匹配就 401。</p><h4 id="场景二-refreshtoken-轮转-—-token-续期" tabindex="-1">场景二：RefreshToken 轮转 — Token 续期 <a class="header-anchor" href="#场景二-refreshtoken-轮转-—-token-续期" aria-label="Permalink to &quot;场景二：RefreshToken 轮转 — Token 续期&quot;">​</a></h4><p>AccessToken(AT) 短期 + RefreshToken(RT) 长期。RT 存入 Redis（<code>refresh:&lt;userId&gt;:&lt;randomId&gt;</code>）。AT 过期后前端用 RT 请求刷新，后端校验 RT → 删旧 RT → 签发新 AT + 新 RT。这就是 <strong>RT 轮转</strong>——每次刷新都换新的 RT，旧的立刻删。如果旧的 RT 被重复使用，大概率泄露了，触发全量清除。</p><h4 id="场景三-会话管理-—-多端登陆与踢人" tabindex="-1">场景三：会话管理 — 多端登陆与踢人 <a class="header-anchor" href="#场景三-会话管理-—-多端登陆与踢人" aria-label="Permalink to &quot;场景三：会话管理 — 多端登陆与踢人&quot;">​</a></h4><p>Redis 存 <code>user_session:&lt;userId&gt;</code> → <code>Set&lt;设备ID&gt;</code>。登录时添加设备 ID，踢人时删除对应设备或清空 Set。拦截器校验当前请求的设备 ID 是否在 Set 中。同时可限制同一用户最多在线设备数，超出时拒绝新登录或踢最早设备。</p><h3 id="_3-2-第一步落地-用户版本号机制-最小改动、最大收益" tabindex="-1">3.2 第一步落地：用户版本号机制（最小改动、最大收益） <a class="header-anchor" href="#_3-2-第一步落地-用户版本号机制-最小改动、最大收益" aria-label="Permalink to &quot;3.2 第一步落地：用户版本号机制（最小改动、最大收益）&quot;">​</a></h3><p>改动前的拦截器链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extractToken → validateToken（验签+过期） → parseToken → LoginUser.set → 放行</span></span></code></pre></div><p>改动后的拦截器链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extractToken → validateToken → parseToken（取出 userId + ver）</span></span>
<span class="line"><span>  → 查 Redis &quot;user:version:&lt;userId&gt;&quot;</span></span>
<span class="line"><span>    → token.ver ≠ Redis.ver → 401（Token 已被注销）</span></span>
<span class="line"><span>    → Redis 挂了或 key 不存在 → 降级放行（信任 JWT 自身有效性）</span></span>
<span class="line"><span>  → LoginUser.set → 放行</span></span></code></pre></div><p><strong>降级策略是关键</strong>：Redis 不可用绝不能导致全站瘫痪。查 Redis 失败时走降级——信任 JWT 本身的签名和过期时间，不额外校验版本号。</p><p><strong>涉及改动的文件</strong>：</p><table tabindex="0"><thead><tr><th>文件</th><th>改动概要</th></tr></thead><tbody><tr><td>JwtUtils</td><td><code>generateAccessToken</code> 新增 version 参数，嵌入 JWT claims</td></tr><tr><td>AuthInterceptor</td><td>preHandle 中新增 Redis 版本号比对逻辑</td></tr><tr><td>UsersServiceImpl.login</td><td>调用 token 生成时传入版本号</td></tr><tr><td>UsersServiceImpl.changePassword</td><td>改密成功后 INCR 版本号</td></tr><tr><td>新增 AuthController</td><td>加 <code>/api/auth/logout</code> 登出接口（目前后端没有）</td></tr><tr><td>前端 user.js</td><td>logout 时先调后端登出接口，再清本地状态</td></tr></tbody></table><p><strong>版本号初始化的处理方式</strong>：首次登录时用 <code>SETNX</code> 确保 key 存在（不存在则初始化为 1），后续只有 INCR 操作。INCR 是原子操作，天然无并发问题。</p><h3 id="_3-3-设计原则总结" tabindex="-1">3.3 设计原则总结 <a class="header-anchor" href="#_3-3-设计原则总结" aria-label="Permalink to &quot;3.3 设计原则总结&quot;">​</a></h3><ol><li><strong>不改 JWT 的无状态优势</strong>：正常请求每个只查一次 Redis（拿版本号），不是每次请求都走黑名单校验</li><li><strong>Redis 不可用时降级放行</strong>：不能让缓存故障导致整个系统不可用</li><li><strong>分步落地</strong>：第一步做版本号，第二步做 RT 轮转，第三步做会话管理，每一步独立验证</li><li><strong>版本号永不自减</strong>：只 INCR，不用 DECR，无回退风险</li></ol><h2 id="四、关键要点" tabindex="-1">四、关键要点 <a class="header-anchor" href="#四、关键要点" aria-label="Permalink to &quot;四、关键要点&quot;">​</a></h2><ul><li><p>JWT jti（JWT ID）是标准字段，方案 A 用到 jti 做黑名单 key 的标识</p></li><li><p><code>SETNX</code> 保证首次初始化幂等，不会覆盖已有的版本号</p></li><li><p>RT 轮转的核心价值不是&quot;让用户不用重新登录&quot;，而是&quot;发现 RT 泄露时能立即止损&quot;</p></li><li><p>拦截器校验顺序：验签 → 过期 → 版本号。签名不对的直接拦截，无需查 Redis</p></li><li><p>Redis key 的 TTL 设计：版本号 key 不设 TTL（或设与 RT 同等长度的 TTL），黑名单 key 的 TTL 等于 token 剩余有效期（过期自动回收内存）</p></li><li><p>前端目前没存 refreshToken，要实现 RT 轮转必须先改前端 user store，让 login 方法同时存储 <code>token</code> 和 <code>refreshToken</code></p><ol><li>降级策略中说&quot;Redis 挂了就信任 JWT 本身&quot;，但如果 Redis 挂掉期间用户改了密码，攻击者拿着旧的、还没过期的 token 仍然能正常访问，这个窗口期怎么缩小？</li><li>版本号方案一次 INCR 踢掉了该用户的所有设备。假如产品要求&quot;改密时只踢其他设备，当前设备不受影响&quot;，Redis 的 key 和 value 结构要怎么重新设计？</li><li>RT 轮转中每次刷新都生成新 RT、删除旧 RT，如果网络抖动前端没收到新 RT，下次还用旧的请求会触发&quot;疑似泄露&quot;告警——这个问题怎么从协议层面优雅地解决？</li></ol></li></ul>`,31)])])}const k=e(d,[["render",n]]);export{u as __pageData,k as default};
